 "content": """"Offline tests for openai_client, backed by a local HTTP server.

No requests ever leave the machine and only dummy credentials are used.
"""

import json
import os
import threading
import unittest
import urllib.error
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

from openai_client import send_request

DUMMY_KEY = "sk-dummy-not-a-real-key"

# Populated by the handler so tests can inspect what the client actually sent.
received = {}


class _Handler(BaseHTTPRequestHandler):
    def do_POST(self):
        length = int(self.headers.get("Content-Length", 0))
        received.clear()
        received.update(
            path=self.path,
            headers=dict(self.headers),
            body=json.loads(self.rfile.read(length).decode("utf-8")),
        )

        if self.path.endswith("/boom/responses"):
            self.send_error(429, "Too Many Requests")
            return

        payload = json.dumps(
            {"id": "resp_123", "model": received["body"]["model"], "ok": True}
        ).encode("utf-8")
        self.send_response(200)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(payload)))
        self.end_headers()
        self.wfile.write(payload)

    def log_message(self, *args):
        pass


class SendRequestTest(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.server = ThreadingHTTPServer(("127.0.0.1", 0), _Handler)
        cls.root = "http://127.0.0.1:%d/v1" % cls.server.server_address[1]
        cls.thread = threading.Thread(target=cls.server.serve_forever, daemon=True)
        cls.thread.start()

    @classmethod
    def tearDownClass(cls):
        cls.server.shutdown()
        cls.server.server_close()
        cls.thread.join()

    def setUp(self):
        os.environ.pop("OPENAI_API_KEY", None)

    def test_posts_expected_url_headers_and_body(self):
        result = send_request(
            "hello there", "gpt-4.1-mini", api_key=DUMMY_KEY, base_url=self.root
        )
        self.assertEqual(result, {"id": "resp_123", "model": "gpt-4.1-mini", "ok": True})
        self.assertEqual(received["path"], "/v1/responses")
        self.assertEqual(received["body"], {"model": "gpt-4.1-mini", "input": "hello there"})
        self.assertEqual(received["headers"]["Authorization"], "Bearer " + DUMMY_KEY)
        self.assertEqual(received["headers"]["Content-Type"], "application/json")

    def test_trailing_slash_in_base_url(self):
        send_request("hi", "m", api_key=DUMMY_KEY, base_url=self.root + "///")
        self.assertEqual(received["path"], "/v1/responses")

    def test_api_key_from_environment(self):
        os.environ["OPENAI_API_KEY"] = "sk-dummy-env-key"
        send_request("hi", "m", base_url=self.root)
        self.assertEqual(received["headers"]["Authorization"], "Bearer sk-dummy-env-key")

    def test_explicit_key_overrides_environment(self):
        os.environ["OPENAI_API_KEY"] = "sk-dummy-env-key"
        send_request("hi", "m", api_key=DUMMY_KEY, base_url=self.root)
        self.assertEqual(received["headers"]["Authorization"], "Bearer " + DUMMY_KEY)

    def test_missing_key_raises_value_error(self):
        with self.assertRaises(ValueError):
            send_request("hi", "m", base_url=self.root)

    def test_empty_env_key_raises_value_error(self):
        os.environ["OPENAI_API_KEY"] = ""
        with self.assertRaises(ValueError):
            send_request("hi", "m", base_url=self.root)

    def test_http_error_propagates(self):
        with self.assertRaises(urllib.error.HTTPError) as ctx:
            send_request("hi", "m", api_key=DUMMY_KEY, base_url=self.root + "/boom")
        self.assertEqual(ctx.exception.code, 429)

    def test_unicode_prompt_round_trips(self):
        send_request("héllo — 世界", "m", api_key=DUMMY_KEY, base_url=self.root)
        self.assertEqual(received["body"]["input"], "héllo — 世界")

    def test_timeout_is_forwarded(self):
        seen = {}
        import urllib.request

        real = urllib.request.urlopen

        def spy(req, timeout=None):
            seen["timeout"] = timeout
            return real(req, timeout=timeout)

        urllib.request.urlopen = spy
        try:
            send_request("hi", "m", api_key=DUMMY_KEY, base_url=self.root, timeout=7)
        finally:
            urllib.request.urlopen = real
        self.assertEqual(seen["timeout"], 7)


if __name__ == "__main__":
    unittest.main(verbosity=2)
